import { AxiosInstance } from 'axios';
import { FrappeAuth } from '..';
import { FrappeCall } from '../call';
import { FrappeDB } from '../db';
import { FrappeFileUpload } from '../file';
import { getAxiosClient } from '../utils/axios';
import { TokenParams } from './types';

export class FrappeApp {
  /** URL of the Frappe instance */
  readonly url: string;

  /** Name of the Frappe App instance */
  readonly name: string;

  /** Axios instance */
  readonly axios: AxiosInstance;

  /** Whether to use token based auth */
  readonly useToken: boolean;

  /** Function that returns the token to be used for authentication */
  readonly token?: () => string;

  /** Type of token to be used for authentication */
  readonly tokenType?: 'Bearer' | 'token';

  /** Custom Headers to be passed in each request */
  readonly customHeaders?: object

  constructor(url: string, tokenParams?: TokenParams, name?: string, customHeaders?: object) {
    this.url = url;
    this.name = name ?? 'FrappeApp';
    this.useToken = [REDACTED] ?? false;
    this.token = [REDACTED];
    this.tokenType = tokenParams?.type ?? 'Bearer';
    this.customHeaders = customHeaders
    this.axios = getAxiosClient(this.url, this.useToken, this.token, this.tokenType, this.customHeaders);
  }

  /** Returns a FrappeAuth object for the app */
  auth() {
    return new FrappeAuth(this.url, this.axios, this.useToken, this.token, this.tokenType);
  }

  /** Returns a FrappeDB object for the app */
  db() {
    return new FrappeDB(this.url, this.axios, this.useToken, this.token, this.tokenType);
  }

  /** Returns a FrappeFileUpload object for the app */
  file() {
    return new FrappeFileUpload(this.url, this.axios, this.useToken, this.token, this.tokenType, this.customHeaders);
  }

  /** Returns a FrappeCall object for the app */
  call() {
    return new FrappeCall(this.url, this.axios, this.useToken, this.token, this.tokenType);
  }
}

import { AxiosInstance } from 'axios';

import { getFrappeError } from '../utils/error';
import { FieldName, Filter, FrappeDoc, GetDocListArgs, GetLastDocArgs } from './types';

export class FrappeDB {
  /** URL of the Frappe App instance */
  private readonly appURL: string;

  /** Axios instance */
  readonly axios: AxiosInstance;

  /** Whether to use the token based auth */
  readonly useToken: boolean;

  /** Token to be used for authentication */
  readonly token?: () => string;

  /** Type of token to be used for authentication */
  readonly tokenType?: 'Bearer' | 'token';

  constructor(
    appURL: string,
    axios: AxiosInstance,
    useToken?: boolean,
    token?: () => string,
    tokenType?: 'Bearer' | 'token',
  ) {
    this.appURL = appURL;
    this.axios = axios;
    this.useToken = useToken ?? false;
    this.token = token;
    this.tokenType = tokenType;
  }

  /**
   * Get a document from the database
   * @param {string} doctype Name of the doctype
   * @param {string} docname Name of the document
   * @returns Promise which resolves to the document object
   */
  async getDoc<T = any>(doctype: string, docname: string = ''): Promise<FrappeDoc<T>> {
    return this.axios
      .get(`/api/resource/${doctype}/${encodeURIComponent(docname)}`)
      .then((res) => res.data.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while fetching the document.');
      });
  }

  /**
   * Gets a list of documents from the database for a particular doctype. Add filters, sorting order and pagination to get a filtered and sorted list of documents.
   * @param {string} doctype Name of the doctype
   * @param {@type GetDocListArgs} [args] Arguments for the query
   * @returns Promise which resolves to an array of documents
   */
  async getDocList<T = any, K = FrappeDoc<T>>(doctype: string, args?: GetDocListArgs<K>) {
    let params = {};

    if (args) {
      const { fields, filters, orFilters, orderBy, limit, limit_start, groupBy, asDict = true } = args;
      const orderByString = orderBy ? `${String(orderBy?.field)} ${orderBy?.order ?? 'asc'}` : '';
      params = {
        fields: fields ? JSON.stringify(fields) : undefined,
        filters: filters ? JSON.stringify(filters) : undefined,
        or_filters: orFilters ? JSON.stringify(orFilters) : undefined,
        order_by: orderByString,
        group_by: groupBy,
        limit,
        limit_start,
        as_dict: asDict,
      };
    }

    return this.axios
      .get<{ data: T[] }>(`/api/resource/${doctype}`, { params })
      .then((res) => res.data.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while fetching the documents.');
      });
  }

  /** Creates a new document in the database
   * @param {string} doctype Name of the doctype
   * @param {Object} value Contents of the document
   * @returns Promise which resolves with the complete document object
   */
  async createDoc<T = any>(doctype: string, value: T): Promise<FrappeDoc<T>> {
    return this.axios
      .post(`/api/resource/${doctype}`, { ...value })
      .then((res) => res.data.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while creating the document.');
      });
  }

  /** Updates a document in the database
   * @param {string} doctype Name of the doctype
   * @param {string} docname Name of the document
   * @param {Object} value Contents of the document to update (only the fields that are to be updated)
   * @returns Promise which resolves with the complete document object
   */
  async updateDoc<T = any>(doctype: string, docname: string | null, value: Partial<T>): Promise<FrappeDoc<T>> {
    return this.axios
      .put(`/api/resource/${doctype}/${docname ? encodeURIComponent(docname) : docname}`, { ...value })
      .then((res) => res.data.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while updating the document.');
      });
  }

  /**
   * Deletes a document in the database
   * @param {string} doctype Name of the doctype
   * @param {string} docname Name of the document
   * @returns Promise which resolves an object with a message "ok"
   */
  async deleteDoc(doctype: string, docname?: string | null): Promise<{ message: string }> {
    return this.axios
      .delete(`/api/resource/${doctype}/${docname ? encodeURIComponent(docname) : docname}`)
      .then((res) => res.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while deleting the document.');
      });
  }

  /**
   * Gets count of documents from the database for a particular doctype with the given filters
   * @param {string} doctype Name of the doctype
   * @param {@type Filter[]} [filters] Filters to be applied in the count query
   * @param {boolean} [debug] Whether to print debug messages or not
   * @returns Promise which resolves a number
   */
  async getCount<T = any>(
    doctype: string,
    filters?: Filter<T>[],
    debug: boolean = false,
  ): Promise<number> {
    const params: any = {
      doctype,
      filters: [],
    };

    if (debug) {
      params.debug = debug;
    }
    if (filters) {
      params.filters = filters ? JSON.stringify(filters) : undefined;
    }

    return this.axios
      .get('/api/method/frappe.client.get_count', { params })
      .then((res) => res.data.message)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while getting the count.');
      });
  }
  /**
   * Get a document from the database
   * @param {string} doctype Name of the doctype
   * @param {@type GetLastDocArgs} [args] Arguments for the query
   * @returns Promise which resolves to the document object
   */
  async getLastDoc<T = any>(doctype: string, args?: GetLastDocArgs<FrappeDoc<T>>): Promise<FrappeDoc<T>> {
    let queryArgs: GetLastDocArgs<FrappeDoc<T>> = {
      orderBy: {
        field: 'creation',
        order: 'desc',
      },
    };
    if (args) {
      queryArgs = {
        ...queryArgs,
        ...args,
      };
    }

    const getDocLists = await this.getDocList<{ name: string }, FrappeDoc<T>>(doctype, {
      ...queryArgs,
      limit: 1,
      fields: ['name'],
    });
    if (getDocLists.length > 0) {
      return this.getDoc<T>(doctype, getDocLists[0].name);
    }

    return {} as FrappeDoc<T>;
  }

  /**
   * Renames a document from the database
   * @param {string} doctype Name of the doctype
   * @param {string} oldname Current name of the document
   * @param {string} newname The new name that will replace the `oldname`
   * @param {boolean} merge  Merges the old document into the new one if a document with `newname` already exists.
   * @returns Promise which resolves with the updated document name
   */
  async renameDoc<T = any>(
    doctype: string,
    oldname: string | null,
    newname: string | null,
    merge: boolean = false,
  ): Promise<FrappeDoc<T>> {
    return this.axios
      .post('/api/method/frappe.client.rename_doc', {
        doctype,
        old_name: oldname,
        new_name: newname,
        merge,
      })
      .then((res) => res.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while renaming the document.');
      });
  }

  /**
   * Retrieves a document's value from the database for a specific doctype using the provided field names and filters.
   * @param {string} doctype Name of the doctype
   * @param {FieldName} [fieldname] - Fields to be returned (default `name`)
   * @param {Filter[]} [filters] Filters to be applied in the get query
   * @param {boolean} asDict Return as dict(object) or list (array)
   * @param {boolean} [debug] Whether to print debug messages or not
   * @param {string} parent Parent doctype name to fetch child table record
   * @returns Promise which resolves an object with specified fieldnames
   */
  async getValue<T = any>(
    doctype: string,
    fieldname?: FieldName,
    filters?: Filter<T>[],
    asDict: boolean = true,
    debug: boolean = false,
    parent: string | null = null,
  ): Promise<T> {
    const params: any = {
      doctype,
      fieldname: '[]',
      filters: [],
      as_dict: asDict,
      debug,
      parent: null,
    };

    if (fieldname) {
      params.fieldname = typeof fieldname === 'object' ? JSON.stringify(fieldname) : fieldname;
    }

    if (filters) {
      params.filters = filters ? JSON.stringify(filters) : undefined;
    }

    if (parent) {
      params.parent = parent;
    }

    return this.axios
      .get('/api/method/frappe.client.get_value', { params })
      .then((res) => res.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while getting the value.');
      });
  }

  /**
   * Sets the field values in the database for the specified doctype.
   * @param {string} doctype Name of the doctype
   * @param {string} name Name of the document
   * @param {string | object} fieldname Fieldname(s) whose value(s) need to be set.
   * @param {any} value Value to be set in fieldname when updating a single field or if `fieldname` is a string.
   * @returns Promise which resolves an updated docoument
   */
  async setValue<T = any>(
    doctype: string,
    name: string,
    fieldname: string | object,
    value?: any,
  ): Promise<FrappeDoc<T>> {
    if (fieldname !== null && typeof fieldname === 'object' && !Array.isArray(fieldname)) {
      value = undefined;
    }

    return this.axios
      .post('/api/method/frappe.client.set_value', {
        doctype,
        name,
        fieldname,
        value,
      })
      .then((res) => res.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while setting the value.');
      });
  }

  /**
   * Retrieves the field value from the database for a specific single doctype.
   * @param {string} doctype Name of the doctype
   * @param {string} field Name of the field
   * @returns Promise that resolves to the field's value.
   */
  async getSingleValue<T = any>(doctype: string, field: string): Promise<T> {
    const params: any = {
      doctype,
      field,
    };

    return this.axios
      .get('/api/method/frappe.client.get_single_value', { params })
      .then((res) => res.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while getting the value of single doctype.');
      });
  }

  /**
   * Submit a document.
   * @param {object} doc Document to be submitted
   * @returns Promise that resolves to a submitted document.
   */
  async submit<T = any>(doc: object): Promise<T> {
    return this.axios
      .post('/api/method/frappe.client.submit', { doc })
      .then((res) => res.data.message)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while submitting the document.');
      });
  }

  /**
   * Cancel a document.
   * @param {string} doctype Name of the doctype
   * @param {string} name Name of the document to be cancelled
   * @returns Promise that resolves to a canceled document.
   */
  async cancel<T = any>(doctype: string, name: string): Promise<FrappeDoc<T>> {
    return this.axios
      .post('/api/method/frappe.client.cancel', { doctype, name })
      .then((res) => res.data)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while cancelling the document.');
      });
  }
}

import { AxiosInstance, AxiosProgressEvent } from 'axios';

import { getFrappeError } from '../utils/error';
import { FileArgs } from './types';
import { getRequestHeaders } from '../utils/axios';

export class FrappeFileUpload {
  /** URL of the Frappe App instance */
  private readonly appURL: string;

  /** Axios instance */
  readonly axios: AxiosInstance;

  /** Whether to use the token based auth */
  readonly useToken: boolean;

  /** Token to be used for authentication */
  readonly token?: () => string;

  /** Type of token to be used for authentication */
  readonly tokenType?: 'Bearer' | 'token';

  /** Custom Headers to be passed in request */
  readonly customHeaders?: object

  constructor(
    appURL: string,
    axios: AxiosInstance,
    useToken?: boolean,
    token?: () => string,
    tokenType?: 'Bearer' | 'token',
    customHeaders?: object
  ) {
    this.appURL = appURL;
    this.axios = axios;
    this.useToken = useToken ?? false;
    this.token = token;
    this.tokenType = tokenType;
    this.customHeaders = customHeaders
  }

  /**
   * Upload file to database
   * @param {File} file to be uploaded
   * @param {@type FileArgs} args arguments of the file
   * @param {VoidFunction} onProgress file upload progress
   * @returns Promise which resolves with the file object
   */
  async uploadFile<T = any>(file: File, args: FileArgs<T>, onProgress?: (bytesUploaded: number, totalBytes?: number, progress?: AxiosProgressEvent) => void, apiPath: string = 'upload_file') {
    const formData = new FormData();
    if (file) formData.append('file', file, file.name);

    const { isPrivate, folder, file_url, doctype, docname, fieldname, otherData } = args;

    if (isPrivate !== undefined) {
      formData.append('is_private', isPrivate ? '1' : '0');
    }
    if (folder) {
      formData.append('folder', folder);
    }
    if (file_url) {
      formData.append('file_url', file_url);
    }
    if (doctype && docname) {
      formData.append('doctype', doctype);
      formData.append('docname', docname);
      if (fieldname) {
        formData.append('fieldname', fieldname);
      }
    }

    if (otherData) {
      Object.keys(otherData).forEach((key: string) => {
        const v = otherData[key as keyof T] as any;
        formData.append(key, v);
      });
    }

    return this.axios
      .post(`/api/method/${apiPath}`, formData, {
        onUploadProgress: (progressEvent) => {
          if (onProgress) {
            onProgress(progressEvent.loaded, progressEvent.total, progressEvent);
          }
        },
        headers: {
          ...getRequestHeaders(this.useToken, this.tokenType, this.token, this.appURL, this.customHeaders),
          'Content-Type': 'multipart/form-data',
        }
      })
      .catch((error) => {
        throw getFrappeError(error, 'There was an error while uploading the file.');
      });
  }
}

import { Error as FrappeError } from '../frappe_app/types';

/**
 * Shapes any axios failure into the `Error` object the SDK throws.
 *
 * Not every failure has a server response: when the device is offline, the
 * request timed out, or the server was unreachable, axios rejects with no
 * `response` at all. The old per-call handlers read `error.response.data`
 * directly, so those failures crashed with "Cannot read properties of
 * undefined" instead of surfacing as a proper error. Here they become a
 * FrappeError with `httpStatus: 0` (the conventional "no HTTP response"
 * value) and axios's own message (e.g. "Network Error", "timeout of 5000ms
 * exceeded") so callers can still tell what happened.
 *
 * A response whose body is not an object (e.g. an HTML error page from a
 * proxy) is also handled: the status is kept, the body is not spread.
 */
export function getFrappeError(error: unknown, fallbackMessage: string): FrappeError {
  const axiosError = error as {
    response?: { data?: unknown; status: number; statusText: string };
    message?: string;
  };
  const response = axiosError?.response;

  if (!response) {
    return {
      httpStatus: 0,
      httpStatusText: '',
      message: axiosError?.message ?? fallbackMessage,
      exception: '',
    };
  }

  const data =
    typeof response.data === 'object' && response.data !== null ? (response.data as Record<string, any>) : {};

  return {
    ...data,
    httpStatus: response.status,
    httpStatusText: response.statusText,
    message: data.message ?? fallbackMessage,
    exception: data.exception ?? data.exc_type ?? '',
  };
}

type Value = string | number | boolean | Date | null;
type SingleValueFilterOperator = '=' | '>' | '<' | '>=' | '<=' | '<>' | 'like' | '!=' | 'Timespan';
type MultiValueFilterOperator = 'in' | 'not in' | 'between';
type FilterVar<T> = keyof T | (string & Record<never, never>);

type SingleValueFilter<T> = [FilterVar<T>, SingleValueFilterOperator, Value];
type MultiValueFilter<T> = [FilterVar<T>, MultiValueFilterOperator, Value[]];
export type Filter<T = FrappeDoc<{}>> = SingleValueFilter<T> | MultiValueFilter<T>;
export type FieldName = string[] | string;

export type FrappeDoc<T> = T & {
  /** User who created the document */
  owner: string;
  /** Date and time when the document was created - ISO format */
  creation: string;
  /** Date and time when the document was last modified - ISO format */
  modified: string;
  /** User who last modified the document */
  modified_by: string;
  idx: number;
  /** 0 - Saved, 1 - Submitted, 2 - Cancelled */
  docstatus: 0 | 1 | 2;
  parent?: any;
  parentfield?: any;
  parenttype?: any;
  /** The primary key of the DocType table */
  name: string;
};

export interface GetLastDocArgs<T = any> {
  filters?: Filter<T>[];
  orFilters?: Filter<T>[];
  orderBy?: {
    field: keyof T | (string & Record<never, never>);
    order?: 'asc' | 'desc';
  };
}

export interface GetDocListArgs<T = any> {
  /** Fields to be fetched */
  fields?: (keyof T | '*')[];
  /** Filters to be applied - SQL AND operation */
  filters?: Filter<T>[];
  /** Filters to be applied - SQL OR operation */
  orFilters?: Filter<T>[];
  /** Fetch from nth document in filtered and sorted list. Used for pagination  */
  limit_start?: number;
  /** Number of documents to be fetched. Default is 20  */
  limit?: number;
  /** Sort results by field and order  */
  orderBy?: {
    field: keyof T | (string & Record<never, never>);
    order?: 'asc' | 'desc';
  };
  /** Group the results by particular field */
  groupBy?: keyof T | (string & Record<never, never>);
  /** Fetch documents as a dictionary */
  asDict?: boolean;
}

import { AxiosInstance } from 'axios';

import { getFrappeError } from '../utils/error';

export class FrappeCall {
  /** URL of the Frappe App instance */
  private readonly appURL: string;

  /** Axios instance */
  readonly axios: AxiosInstance;

  /** Whether to use the token based auth */
  readonly useToken: boolean;

  /** Token to be used for authentication */
  readonly token?: () => string;

  /** Type of token to be used for authentication */
  readonly tokenType?: 'Bearer' | 'token';

  constructor(
    appURL: string,
    axios: AxiosInstance,
    useToken?: boolean,
    token?: () => string,
    tokenType?: 'Bearer' | 'token',
  ) {
    this.appURL = appURL;
    this.axios = axios;
    this.useToken = useToken ?? false;
    this.token = token;
    this.tokenType = tokenType;
  }

  /** Makes a GET request to the specified endpoint */
  async get<T = any>(path: string, params?: Record<string, any>): Promise<T> {

    const encodedParams = new URLSearchParams();
    // TEMP Fix Issue #50
    if (params) {
      Object.entries(params).forEach(param => {
        const [key, value] = param;
        if (value !== null && value !== undefined) {
          const val = typeof value === 'object' ? JSON.stringify(value) : value;
          encodedParams.set(key, val);
        }
      })
    }

    return this.axios
      .get(`/api/method/${path}`, {
        params: encodedParams,
      })
      .then((res) => res.data as T)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error.');
      });
  }

  /** Makes a POST request to the specified endpoint */
  async post<T = any>(path: string, params?: any): Promise<T> {
    return this.axios
      .post(`/api/method/${path}`, { ...params })
      .then((res) => res.data as T)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error.');
      });
  }

  /** Makes a PUT request to the specified endpoint */
  async put<T = any>(path: string, params?: any): Promise<T> {
    return this.axios
      .put(`/api/method/${path}`, { ...params })
      .then((res) => res.data as T)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error.');
      });
  }

  /** Makes a DELETE request to the specified endpoint */
  async delete<T = any>(path: string, params?: any): Promise<T> {
    return this.axios
      .delete(`/api/method/${path}`, { params })
      .then((res) => res.data as T)
      .catch((error) => {
        throw getFrappeError(error, 'There was an error.');
      });
  }
}

import axios, { AxiosInstance, RawAxiosRequestHeaders } from 'axios';

export function getAxiosClient(
  appURL: string,
  useToken?: boolean,
  token?: () => string,
  tokenType?: 'Bearer' | 'token',
  customHeaders?: object
): AxiosInstance {
  const axiosInstance = axios.create({
    baseURL: appURL,
    headers: getRequestHeaders(useToken, tokenType, token, appURL, customHeaders),
    withCredentials: true,
  });

  // Add request interceptor to dynamically set CSRF token and auth token
  axiosInstance.interceptors.request.use((config) => {
    // Update CSRF token on each request if available
    if (typeof window !== 'undefined' && window.csrf_token && window.csrf_token !== '{{ csrf_token }}') {
      config.headers['X-Frappe-CSRF-Token'] = window.csrf_token;
    }

    // Update authorization token if using token auth
    if (useToken && tokenType && token) {
      config.headers.Authorization = [REDACTED]} ${token()}`;
    }

    return config;
  });

  return axiosInstance;
}

export function getRequestHeaders(
  useToken: boolean = false,
  tokenType?: 'Bearer' | 'token',
  token?: () => string,
  appURL?: string,
  customHeaders?: object
): RawAxiosRequestHeaders {
  const headers: RawAxiosRequestHeaders = {
    Accept: 'application/json',
    'Content-Type': 'application/json; charset=utf-8',
  };

  if (useToken && tokenType && token) {
    headers.Authorization = [REDACTED]} ${token()}`;
  }

  // in case of browser environments
  if (typeof window !== 'undefined' && typeof document !== 'undefined') {
    if (window.location) {
      if (appURL && appURL !== window.location.origin) {
        // Do not set X-Frappe-Site-Name
      } else {
        headers['X-Frappe-Site-Name'] = window.location.hostname;
      }
    }
    if (window.csrf_token && window.csrf_token !== '{{ csrf_token }}') {
      headers['X-Frappe-CSRF-Token'] = window.csrf_token;
    }
  }

  return {
    ...headers,
    ...(customHeaders ?? {})
  };
}
